import 'package:flutter/material.dart';\nimport '../models/ai_tool.dart';\nimport '../services/firebase_service.dart';\n\nclass AIToolsProvider with ChangeNotifier {\n  final FirebaseService _firebaseService = FirebaseService();\n\n  List<AITool> _allTools = [];\n  List<AITool> _filteredTools = [];\n  List<AITool> _trendingTools = [];\n  Map<String, List<AITool>> _toolsByCategory = {};\n  bool _isLoading = false;\n  String _searchQuery = '';\n\n  List<AITool> get allTools => _allTools;\n  List<AITool> get filteredTools => _filteredTools;\n  List<AITool> get trendingTools => _trendingTools;\n  Map<String, List<AITool>> get toolsByCategory => _toolsByCategory;\n  bool get isLoading => _isLoading;\n  String get searchQuery => _searchQuery;\n\n  AIToolsProvider() {\n    loadAllTools();\n  }\n\n  Future<void> loadAllTools() async {\n    _isLoading = true;\n    notifyListeners();\n\n    try {\n      _allTools = await _firebaseService.getAllTools();\n      _trendingTools = await _firebaseService.getTrendingTools();\n      _filteredTools = _allTools;\n\n      _toolsByCategory = {};\n      for (final tool in _allTools) {\n        if (!_toolsByCategory.containsKey(tool.category)) {\n          _toolsByCategory[tool.category] = [];\n        }\n        _toolsByCategory[tool.category]!.add(tool);\n      }\n    } catch (e) {\n      print('Error: $e');\n    } finally {\n      _isLoading = false;\n      notifyListeners();\n    }\n  }\n\n  Future<void> loadToolsByCategory(String category) async {\n    _isLoading = true;\n    notifyListeners();\n\n    try {\n      final tools = await _firebaseService.getToolsByCategory(category);\n      _filteredTools = tools;\n    } catch (e) {\n      print('Error: $e');\n    } finally {\n      _isLoading = false;\n      notifyListeners();\n    }\n  }\n\n  Future<void> searchTools(String query) async {\n    _searchQuery = query;\n\n    if (query.isEmpty) {\n      _filteredTools = _allTools;\n    } else {\n      _isLoading = true;\n      notifyListeners();\n\n      try {\n        _filteredTools = await _firebaseService.searchTools(query);\n      } catch (e) {\n        print('Error: $e');\n      } finally {\n        _isLoading = false;\n        notifyListeners();\n      }\n    }\n\n    notifyListeners();\n  }\n\n  List<String> getCategories() {\n    return _toolsByCategory.keys.toList();\n  }\n\n  List<AITool> getToolsBySpecificCategory(String category) {\n    return _toolsByCategory[category] ?? [];\n  }\n}\n